    "batch-research-final-441-q040": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "The reported p = 0.666 is much larger than 0.05, so the observed mean birth-weight difference is not statistically significant at that threshold. This does not prove equal mean weights.", "evidence": {"title": "27) Statistical significance of data using p-value", "sourceId": "1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy", "page": 6, "unit": "page", "quote": "p-value ≤ α ⇒ Reject H 0 at level α p-value > α ⇒ Do not reject H0at level α", "url": "https://drive.google.com/file/d/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "838dab0bdc3184729b37ecb0e48acdcca571478994c59842d3cea96e348ec34c", "relation": "direct", "image": "lecture-media/research-final-review/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy-p06.jpg"}}},
    "batch-research-final-439-q001": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "The central 95% of a normal distribution is approximately μ ± 2σ. With mean 70 and SD 10, that gives 50 to 90 mmHg.", "evidence": {"title": "26)Normal distribution & its application", "sourceId": "1dHie2JtsKJb2NbdkNsClnYqJYzLYHgfl", "page": 5, "unit": "page", "quote": "1 standard deviation on both sides of the mean includes approximately 68% of the total area", "url": "https://drive.google.com/file/d/1dHie2JtsKJb2NbdkNsClnYqJYzLYHgfl/view#page=5", "cohortLabel": "MED444 teaching notes", "sourceSha256": "67660e9c2bcbcceb269048db42f7d81f47c2a7b10341936abb9c2e39a3838403", "relation": "direct", "image": "lecture-media/research-final-review/1dHie2JtsKJb2NbdkNsClnYqJYzLYHgfl-p05.jpg"}}},
    "batch-research-final-439-q004": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "A p-value is a probability calculated under a null model. It lies between 0 and 1.", "evidence": {"title": "27) Statistical significance of data using p-value", "sourceId": "1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy", "page": 7, "unit": "page", "quote": "Calculated as the probability of an effect as large as or larger than the observed effect", "url": "https://drive.google.com/file/d/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy/view#page=7", "cohortLabel": "MED444 teaching notes", "sourceSha256": "838dab0bdc3184729b37ecb0e48acdcca571478994c59842d3cea96e348ec34c", "relation": "direct", "image": "lecture-media/research-final-review/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy-p07.jpg"}}},
