    "batch-research-final-439-q030": {"review": {"answers": [], "confidence": "unresolved", "basis": "concept", "explanation": "Sparse expected counts undermine the χ² approximation. An exact r × c test or a Monte Carlo exact-test approximation can retain the original categories. Combining categories is also possible when scientifically justified, but sparse counts alone do not require collapsing them.", "references": [{"title": "R stats · Fisher’s exact test", "url": "https://stat.ethz.ch/R-manual/R-devel/library/stats/html/fisher.test.html"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
    "batch-research-final-439-q031": {"review": {"answers": ["D"], "confidence": "supported", "basis": "concept", "explanation": "Compare counts of smokers and nonsmokers across the three independent regions. This is a χ² test of homogeneity if expected counts support the approximation.", "references": [{"title": "R stats · Pearson’s chi-squared test", "url": "https://stat.ethz.ch/R-manual/R-devel/library/stats/html/chisq.test.html"}]}},
