    "batch-research-final-439-q034": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "The comparison is between two independent hypertension proportions in the urban and rural samples. The two-proportion z test is suitable if both categories have adequate expected counts; with sparse counts consider an exact test.", "evidence": {"title": "27) Statistical significance of data using p-value", "sourceId": "1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy", "page": 6, "unit": "page", "quote": "Statistical test for p1–p2 Two Population Proportions, Independent Samples", "url": "https://drive.google.com/file/d/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "838dab0bdc3184729b37ecb0e48acdcca571478994c59842d3cea96e348ec34c", "relation": "direct", "image": "lecture-media/research-final-review/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy-p06.jpg"}}},
