    "batch-research-final-439-q040": {"review": {"answers": ["B"], "confidence": "supported", "basis": "concept", "explanation": "The difference interval of −5.15 to 16.43 contains zero, so the corresponding two-sided test has p > 0.05. The interval still allows both a decrease and an increase.", "references": [{"title": "NIST · Confidence limits for the mean", "url": "https://www.itl.nist.gov/div898/handbook/eda/section3/eda352.htm"}]}},
    "batch-research-final-439-q041": {"review": {"answers": ["D"], "confidence": "supported", "basis": "lecture", "explanation": "A p-value helps assess compatibility with the null hypothesis. A confidence interval shows the precision and range of effect sizes compatible with the model. Reporting the effect estimate alongside both gives the most informative result.", "evidence": {"title": "27) Statistical significance of data using p-value", "sourceId": "1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy", "page": 6, "unit": "page", "quote": "p-value ≤ α ⇒ Reject H 0 at level α p-value > α ⇒ Do not reject H0at level α", "url": "https://drive.google.com/file/d/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "838dab0bdc3184729b37ecb0e48acdcca571478994c59842d3cea96e348ec34c", "relation": "direct", "image": "lecture-media/research-final-review/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy-p06.jpg"}, "references": [{"title": "NIST · Confidence limits for the mean", "url": "https://www.itl.nist.gov/div898/handbook/eda/section3/eda352.htm"}]}},
    "batch-research-final-439-q042": {"review": {"answers": [], "confidence": "unresolved", "basis": "lecture", "explanation": "OR = 2.6 is the point estimate. A p-value above 0.05 means the test does not reject the null of OR = 1 at that threshold. The p-value is not the probability that an odds ratio of 2.6 was caused by chance.", "evidence": {"title": "27) Statistical significance of data using p-value", "sourceId": "1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy", "page": 7, "unit": "page", "quote": "Calculated as the probability of an effect as large as or larger than the observed effect", "url": "https://drive.google.com/file/d/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy/view#page=7", "cohortLabel": "MED444 teaching notes", "sourceSha256": "838dab0bdc3184729b37ecb0e48acdcca571478994c59842d3cea96e348ec34c", "relation": "direct", "image": "lecture-media/research-final-review/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy-p07.jpg"}, "references": [{"title": "CDC · Field Epidemiology Manual, interpreting data", "url": "https://www.cdc.gov/field-epi-manual/php/chapters/analyze-interpret-data.html"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
    "batch-research-final-439-q044": {"review": {"answers": ["B"], "confidence": "supported", "basis": "lecture", "explanation": "The value 116 appears three times in the listed weights; every other value appears once. The mode is 116 lb even though the stem's stated sample count and its list disagree.", "evidence": {"title": "24)Descriptive Statistics (Summary & Variability measures)", "sourceId": "1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6", "page": 6, "unit": "page", "quote": "Value that occursmost often Used for either numerical or categorical(nominal) data", "url": "https://drive.google.com/file/d/1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "31234ec21b90dcc0f65c7077cb1ac855f448e7bd3b7b2d61d73275de1aecbb7f", "relation": "direct", "image": "lecture-media/research-final-review/1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6-p06.jpg"}}},
