    "batch-research-final-438-q003": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "In ascending order the five weights are 110, 116, 124, 131, and 168 lb. The third value, 124 lb, is the median.", "evidence": {"title": "24)Descriptive Statistics (Summary & Variability measures)", "sourceId": "1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6", "page": 5, "unit": "page", "quote": "IfN, the number ofvalues is even, themedian is the average of themiddle twovalues.", "url": "https://drive.google.com/file/d/1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6/view#page=5", "cohortLabel": "MED444 teaching notes", "sourceSha256": "31234ec21b90dcc0f65c7077cb1ac855f448e7bd3b7b2d61d73275de1aecbb7f", "relation": "direct", "image": "lecture-media/research-final-review/1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6-p05.jpg"}}},
    "batch-research-final-438-q005": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "Independent groups with a quantitative outcome call for an independent-samples t test under its assumptions. Small samples make distributional assumptions more important. Welch's form avoids assuming equal variances.", "evidence": {"title": "Statistical test for quantitative variables", "sourceId": "1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3", "page": 9, "unit": "page", "quote": "t-test (two independent means)", "url": "https://drive.google.com/file/d/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3/view#page=9", "cohortLabel": "MED444 teaching notes", "sourceSha256": "5508b212d1a42b3bc4816428a5128642018986625ac06366dbc33f9859c727f6", "relation": "direct", "image": "lecture-media/research-final-review/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3-p09.jpg"}}},
    "batch-research-final-438-q006": {"review": {"answers": ["B"], "confidence": "supported", "basis": "concept", "explanation": "Fisher's exact test evaluates the association in a 2 × 2 table without relying on the large-sample χ² approximation. It is useful when expected counts are small.", "references": [{"title": "R stats · Fisher’s exact test", "url": "https://stat.ethz.ch/R-manual/R-devel/library/stats/html/fisher.test.html"}]}},
    "batch-research-final-438-q008": {"review": {"answers": ["B"], "confidence": "supported", "basis": "lecture", "explanation": "SD is the square root of the variance. With variance 9, SD is 3.", "evidence": {"title": "24)Descriptive Statistics (Summary & Variability measures)", "sourceId": "1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6", "page": 11, "unit": "page", "quote": "take the square root of the variance Return to original units rather than squared units", "url": "https://drive.google.com/file/d/1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6/view#page=11", "cohortLabel": "MED444 teaching notes", "sourceSha256": "31234ec21b90dcc0f65c7077cb1ac855f448e7bd3b7b2d61d73275de1aecbb7f", "relation": "direct", "image": "lecture-media/research-final-review/1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6-p11.jpg"}}},
