    "batch-research-final-438-q017": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "A frequency curve can show how a continuous variable is distributed along its scale. A pie chart or standard bar chart uses discrete categories.", "evidence": {"title": "24)Descriptive Statistics (Summary & Variability measures)", "sourceId": "1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6", "page": 13, "unit": "page", "quote": "Categorical data Bar chart Clustered bar charts (two categoricalvariables) Pie charts Continuous data Histogram", "url": "https://drive.google.com/file/d/1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6/view#page=13", "cohortLabel": "MED444 teaching notes", "sourceSha256": "31234ec21b90dcc0f65c7077cb1ac855f448e7bd3b7b2d61d73275de1aecbb7f", "relation": "direct", "image": "lecture-media/research-final-review/1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6-p13.jpg"}}},
    "batch-research-final-438-q019": {"review": {"answers": ["D"], "confidence": "supported", "basis": "lecture", "explanation": "The empirical rule gives about 99.7% of normally distributed individual values within three standard deviations. With mean 70 and SD 10, that spans 40 to 100 mmHg. Exactly 99% would use about 2.576 SDs, so D is the intended approximation.", "evidence": {"title": "26)Normal distribution & its application", "sourceId": "1dHie2JtsKJb2NbdkNsClnYqJYzLYHgfl", "page": 5, "unit": "page", "quote": "1 standard deviation on both sides of the mean includes approximately 68% of the total area", "url": "https://drive.google.com/file/d/1dHie2JtsKJb2NbdkNsClnYqJYzLYHgfl/view#page=5", "cohortLabel": "MED444 teaching notes", "sourceSha256": "67660e9c2bcbcceb269048db42f7d81f47c2a7b10341936abb9c2e39a3838403", "relation": "direct", "image": "lecture-media/research-final-review/1dHie2JtsKJb2NbdkNsClnYqJYzLYHgfl-p05.jpg"}}},
    "batch-research-final-432-q005": {"review": {"answers": [], "confidence": "unresolved", "basis": "lecture", "explanation": "A 99% confidence interval for the mean needs the standard error, which cannot be computed from the information given. If the recall meant a range containing about 99.7% of normally distributed individual values, 70 ± 3 × 10 gives 40 to 100, but that is a different quantity.", "evidence": {"title": "26)Normal distribution & its application", "sourceId": "1dHie2JtsKJb2NbdkNsClnYqJYzLYHgfl", "page": 5, "unit": "page", "quote": "1 standard deviation on both sides of the mean includes approximately 68% of the total area", "url": "https://drive.google.com/file/d/1dHie2JtsKJb2NbdkNsClnYqJYzLYHgfl/view#page=5", "cohortLabel": "MED444 teaching notes", "sourceSha256": "67660e9c2bcbcceb269048db42f7d81f47c2a7b10341936abb9c2e39a3838403", "relation": "direct", "image": "lecture-media/research-final-review/1dHie2JtsKJb2NbdkNsClnYqJYzLYHgfl-p05.jpg"}, "references": [{"title": "NIST · Confidence limits for the mean", "url": "https://www.itl.nist.gov/div898/handbook/eda/section3/eda352.htm"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
    "batch-research-final-438-q023": {"review": {"answers": [], "confidence": "unresolved", "basis": "lecture", "explanation": "OR = 4.5 gives the direction and magnitude of the observed association. At α = 0.05, p < 0.05 is evidence against OR = 1 under the test model. It does not tell us whether the observation was or was not due to chance.", "evidence": {"title": "27) Statistical significance of data using p-value", "sourceId": "1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy", "page": 7, "unit": "page", "quote": "Calculated as the probability of an effect as large as or larger than the observed effect", "url": "https://drive.google.com/file/d/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy/view#page=7", "cohortLabel": "MED444 teaching notes", "sourceSha256": "838dab0bdc3184729b37ecb0e48acdcca571478994c59842d3cea96e348ec34c", "relation": "direct", "image": "lecture-media/research-final-review/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy-p07.jpg"}, "references": [{"title": "CDC · Field Epidemiology Manual, interpreting data", "url": "https://www.cdc.gov/field-epi-manual/php/chapters/analyze-interpret-data.html"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
    "batch-research-final-438-q029": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "Standard error quantifies the sampling variability of an estimator, such as a mean or proportion. Standard deviation instead describes variation among individual observations.", "evidence": {"title": "Statistical test for quantitative variables", "sourceId": "1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3", "page": 6, "unit": "page", "quote": "Standard error = SEM1 = SD/ Sample size = 4.1/ √42 = 0.633", "url": "https://drive.google.com/file/d/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "5508b212d1a42b3bc4816428a5128642018986625ac06366dbc33f9859c727f6", "relation": "direct", "image": "lecture-media/research-final-review/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3-p06.jpg"}}},
