    "batch-research-final-438-q030": {"review": {"answers": ["B"], "confidence": "supported", "basis": "lecture", "explanation": "A statistic summarizes a sample. A parameter summarizes the population from which that sample was drawn.", "evidence": {"title": "Statistical test for quantitative variables", "sourceId": "1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3", "page": 4, "unit": "page", "quote": "Is there a difference between the parameter (2.70) and the statistic (3.00)", "url": "https://drive.google.com/file/d/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3/view#page=4", "cohortLabel": "MED444 teaching notes", "sourceSha256": "5508b212d1a42b3bc4816428a5128642018986625ac06366dbc33f9859c727f6", "relation": "direct", "image": "lecture-media/research-final-review/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3-p04.jpg"}}},
    "batch-research-final-438-q032": {"review": {"answers": ["A"], "confidence": "supported", "basis": "concept", "explanation": "The confidence interval for the difference between the two group means is 5.15 to 16.43. It excludes zero, so p < 0.05 for the matching two-sided test.", "references": [{"title": "NIST · Confidence limits for the mean", "url": "https://www.itl.nist.gov/div898/handbook/eda/section3/eda352.htm"}]}},
    "batch-research-final-438-q036": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "The central area within one SD on either side of the mean is about 68.3% of a normal distribution.", "evidence": {"title": "26)Normal distribution & its application", "sourceId": "1dHie2JtsKJb2NbdkNsClnYqJYzLYHgfl", "page": 5, "unit": "page", "quote": "1 standard deviation on both sides of the mean includes approximately 68% of the total area", "url": "https://drive.google.com/file/d/1dHie2JtsKJb2NbdkNsClnYqJYzLYHgfl/view#page=5", "cohortLabel": "MED444 teaching notes", "sourceSha256": "67660e9c2bcbcceb269048db42f7d81f47c2a7b10341936abb9c2e39a3838403", "relation": "direct", "image": "lecture-media/research-final-review/1dHie2JtsKJb2NbdkNsClnYqJYzLYHgfl-p05.jpg"}}},
    "batch-research-final-438-q043": {"review": {"answers": ["B"], "confidence": "supported", "basis": "concept", "explanation": "The relative risk point estimate of 1.36 suggests higher risk, but its interval of 0.76 to 2.60 includes 1. A high absolute risk or a significant association cannot be inferred from these results.", "references": [{"title": "CDC · Field Epidemiology Manual, interpreting data", "url": "https://www.cdc.gov/field-epi-manual/php/chapters/analyze-interpret-data.html"}, {"title": "NIST · Confidence limits for the mean", "url": "https://www.itl.nist.gov/div898/handbook/eda/section3/eda352.htm"}]}, "ungradedReason": "The reviewed answer differs from the original Gift key."},
    "batch-research-final-438-q047": {"review": {"answers": ["B"], "confidence": "supported", "basis": "concept", "explanation": "For paired binary outcomes in the same people or matched pairs, use McNemar's test. It compares the two kinds of discordant pairs. If pre- and post-intervention samples were independent, a two-sample proportion test would be used instead.", "references": [{"title": "R stats · McNemar’s chi-squared test", "url": "https://stat.ethz.ch/R-manual/R-devel/library/stats/html/mcnemar.test.html"}]}},
