    "batch-research-final-435-q013": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "The reported p = 0.01 is below the conventional 0.05 threshold, so the BMI difference is statistically significant at that level. The size and importance of the difference require an effect estimate.", "evidence": {"title": "27) Statistical significance of data using p-value", "sourceId": "1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy", "page": 6, "unit": "page", "quote": "p-value ≤ α ⇒ Reject H 0 at level α p-value > α ⇒ Do not reject H0at level α", "url": "https://drive.google.com/file/d/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "838dab0bdc3184729b37ecb0e48acdcca571478994c59842d3cea96e348ec34c", "relation": "direct", "image": "lecture-media/research-final-review/1cR2lMEgvp2Y7N35bTeimuLpK0VSgi9Jy-p06.jpg"}}},
