    "batch-research-final-433-q018": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "With the underlying SD held fixed, the standard error of the mean is proportional to 1/√n. Increasing sample size reduces the variation of sample means; it does not systematically reduce the variation of individual measurements.", "evidence": {"title": "Statistical test for quantitative variables", "sourceId": "1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3", "page": 6, "unit": "page", "quote": "Standard error = SEM1 = SD/ Sample size = 4.1/ √42 = 0.633", "url": "https://drive.google.com/file/d/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "5508b212d1a42b3bc4816428a5128642018986625ac06366dbc33f9859c727f6", "relation": "direct", "image": "lecture-media/research-final-review/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3-p06.jpg"}}},
    "batch-research-final-435-q040": {"review": {"answers": ["D"], "confidence": "supported", "basis": "concept", "explanation": "The 95% is a property of the interval procedure. If sampling and interval construction were repeated under the same assumptions, about 95% of the resulting intervals would include the fixed true mean. D expresses that long-run coverage more precisely than B.", "references": [{"title": "NIST · Confidence limits for the mean", "url": "https://www.itl.nist.gov/div898/handbook/eda/section3/eda352.htm"}]}, "ungradedReason": "The reviewed answer differs from the original Gift key."},
    "batch-research-final-435-q042": {"review": {"answers": ["D"], "confidence": "supported", "basis": "lecture", "explanation": "With 20 women and a sample SD of 10, SE = 10/√20 ≈ 2.236 beats per minute. D is the closest rounding.", "evidence": {"title": "Statistical test for quantitative variables", "sourceId": "1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3", "page": 6, "unit": "page", "quote": "Standard error = SEM1 = SD/ Sample size = 4.1/ √42 = 0.633", "url": "https://drive.google.com/file/d/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "5508b212d1a42b3bc4816428a5128642018986625ac06366dbc33f9859c727f6", "relation": "direct", "image": "lecture-media/research-final-review/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3-p06.jpg"}}},
    "batch-research-final-435-q043": {"review": {"answers": [], "confidence": "unresolved", "basis": "lecture", "explanation": "With population mean 200, SD 14 and n = 9, z for a sample mean of 170 is (170 − 200)/(14/√9) ≈ −6.43. The Gift uses −2.14, obtained by treating 170 as a single observation. The recall describes a sample mean.", "evidence": {"title": "T13) Normal distribution", "sourceId": "1fXX2QWU-DFtIF_7WBiGgkLDR62dJWPI_", "page": 3, "unit": "page", "quote": "Z= Observation - Mean Standard deviation", "url": "https://drive.google.com/file/d/1fXX2QWU-DFtIF_7WBiGgkLDR62dJWPI_/view#page=3", "cohortLabel": "MED444 teaching notes", "sourceSha256": "83d7ef3cc61cbdf8d1c42426e5a117d8599ecb50b45e2ef73308bc0036f04038", "relation": "direct", "image": "lecture-media/research-final-review/1fXX2QWU-DFtIF_7WBiGgkLDR62dJWPI_-p03.jpg"}, "references": [{"title": "Statistical test for quantitative variables · MED444 PDF p. 6", "url": "https://drive.google.com/file/d/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3/view#page=6"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
    "batch-research-final-435-q046": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "Choose the test from outcome type, how many groups are compared, whether those groups are independent or paired, and whether sample size or expected counts support the method.", "evidence": {"title": "Statistical test for quantitative variables", "sourceId": "1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3", "page": 3, "unit": "page", "quote": "Study variable 2 Qualitative Qualitative Outcome variable 3 Quantitative 4 Quantitative", "url": "https://drive.google.com/file/d/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3/view#page=3", "cohortLabel": "MED444 teaching notes", "sourceSha256": "5508b212d1a42b3bc4816428a5128642018986625ac06366dbc33f9859c727f6", "relation": "direct", "image": "lecture-media/research-final-review/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3-p03.jpg"}}},
    "batch-research-final-434-q046": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "Choose the test from outcome type, how many groups are compared, whether those groups are independent or paired, and whether sample size or expected counts support the method.", "evidence": {"title": "Statistical test for quantitative variables", "sourceId": "1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3", "page": 3, "unit": "page", "quote": "Study variable 2 Qualitative Qualitative Outcome variable 3 Quantitative 4 Quantitative", "url": "https://drive.google.com/file/d/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3/view#page=3", "cohortLabel": "MED444 teaching notes", "sourceSha256": "5508b212d1a42b3bc4816428a5128642018986625ac06366dbc33f9859c727f6", "relation": "direct", "image": "lecture-media/research-final-review/1gYDP5xxLiD_qrrGZ2kszC7e0OPBNixm3-p03.jpg"}}},
    "batch-research-final-435-q047": {"review": {"answers": ["B"], "confidence": "supported", "basis": "concept", "explanation": "With equal bin widths, the histogram height is proportional to each bin's count. If widths differ, use frequency density so the bar area represents the count. Grouping into bins loses the exact individual values.", "references": [{"title": "NIST · Histogram", "url": "https://www.itl.nist.gov/div898/handbook/eda/section3/histogra.htm"}]}},
    "batch-research-final-435-q048": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "An ordered list of 42 values has two central positions, 21 and 22. Average those two values to find the median.", "evidence": {"title": "24)Descriptive Statistics (Summary & Variability measures)", "sourceId": "1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6", "page": 5, "unit": "page", "quote": "IfN, the number ofvalues is even, themedian is the average of themiddle twovalues.", "url": "https://drive.google.com/file/d/1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6/view#page=5", "cohortLabel": "MED444 teaching notes", "sourceSha256": "31234ec21b90dcc0f65c7077cb1ac855f448e7bd3b7b2d61d73275de1aecbb7f", "relation": "direct", "image": "lecture-media/research-final-review/1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6-p05.jpg"}}},
    "batch-research-final-435-q049": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "An SD is the square root of its variance, so √4 = 2. The mean of 10 is not used.", "evidence": {"title": "24)Descriptive Statistics (Summary & Variability measures)", "sourceId": "1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6", "page": 11, "unit": "page", "quote": "take the square root of the variance Return to original units rather than squared units", "url": "https://drive.google.com/file/d/1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6/view#page=11", "cohortLabel": "MED444 teaching notes", "sourceSha256": "31234ec21b90dcc0f65c7077cb1ac855f448e7bd3b7b2d61d73275de1aecbb7f", "relation": "direct", "image": "lecture-media/research-final-review/1PqvMw6LbL7-SmTHQJ_m7MlSvman1BWd6-p11.jpg"}}},
